@pytest.mark.parametrize("name", ADDED_CONTEXT_NAMES)
def test_named_call_is_a_context_call(name: str) -> None:
    assert dax_failing_type_tests.is_context_call(("call", name, (("number", 1),)))


@pytest.mark.parametrize("name", ADDED_CONTEXT_NAMES)
def test_variant_below_the_name_stays_refused(name: str) -> None:
    variant = parse_expression('ABS(IF(MAX(Facts[Sales])>15,2,"7"))')
    assert dax_failing_type_tests.context_changing(("call", "COUNTROWS", (("call", name, (variant,)),)))
    if name in dax_failing_type_tests._CONTEXT_CALLS_BELOW:  # a name of the second list touches only a Variant below it; the first list refuses whatever stands below
        assert not dax_failing_type_tests.context_changing(("binary", "+", variant, ("call", "COUNTROWS", (("call", name, (("table", "FACTS"),)),))))


def test_variant_result_branches_follow_nested_conditionals() -> None:
    from analytics_studio import measures

    node = parse_expression('IF(MAX(Facts[Sales])>15,MAX(Facts[Note]),COALESCE(SUM(Facts[Quantity]),CALCULATE(2)))')
    assert len(measures._variant_result_branches(node)) == 3


def test_filter_state_reads_are_found() -> None:
    from analytics_studio import measures

    assert measures._reads_filter_state_of(parse_expression("IF(HASONEVALUE(Facts[Region]),1,0)"), None)
    assert measures._reads_filter_state_of(parse_expression("IF(HASONEVALUE(Facts[Region]),1,0)"), ["region"])
    assert not measures._reads_filter_state_of(parse_expression("IF(HASONEVALUE(Facts[Region]),1,0)"), ["note"])
    assert not measures._reads_filter_state_of(parse_expression("SUM(Facts[Quantity])"), None)


